// Runs after npm install/ci. Some npm packages ship Go sources (e.g.
// flatted/golang), and `go test ./...` / `golangci-lint run ./...` in the
// repo root would pick them up as packages of the colonyhall module. A
// go.mod in node_modules makes it a separate module, which ./... skips.
import { writeFileSync } from "node:fs";

writeFileSync(
  new URL("../node_modules/go.mod", import.meta.url),
  "// Generated by web/scripts/go-ignore-node-modules.mjs: keeps node_modules out of the Go module.\nmodule colonyhall.invalid/node_modules\n",
);
